package auth

import (
	"crypto/hmac"
	"crypto/sha256"
	"encoding/hex"
	"fmt"
	"log"
	"strconv"
	"strings"
	"sync"
	"time"
)

const (
	nonceWindowSeconds = 300
	maxNonceCache      = 10000
)

type AuditEntry struct {
	Timestamp time.Time
	UserID    string
	Action    string
	Success   bool
	Nonce     string
}

type NonceStore struct {
	mu     sync.RWMutex
	nonces map[string]int64
}

func NewNonceStore() *NonceStore {
	return &NonceStore{
		nonces: make(map[string]int64),
	}
}

func (ns *NonceStore) CheckAndStore(nonce string, timestamp int64) bool {
	ns.mu.Lock()
	defer ns.mu.Unlock()

	// Evict expired nonces periodically
	if len(ns.nonces) > maxNonceCache {
		now := time.Now().Unix()
		for k, v := range ns.nonces {
			if now-v > nonceWindowSeconds {
				delete(ns.nonces, k)
			}
		}
	}

	if _, exists := ns.nonces[nonce]; exists {
		return false // nonce already used
	}

	ns.nonces[nonce] = timestamp
	return true
}

type Authenticator struct {
	secretKey  []byte
	nonceStore *NonceStore
	auditLog   []AuditEntry
	auditMu    sync.Mutex
}

func NewAuthenticator(secret string) *Authenticator {
	return &Authenticator{
		secretKey:  []byte(secret),
		nonceStore: NewNonceStore(),
		auditLog:   make([]AuditEntry, 0),
	}
}

func (a *Authenticator) computeSignature(userID, nonce string, timestamp int64) string {
	message := fmt.Sprintf("%s|%s|%d", userID, nonce, timestamp)
	mac := hmac.New(sha256.New, a.secretKey)
	mac.Write([]byte(message))
	return hex.EncodeToString(mac.Sum(nil))
}

func (a *Authenticator) logAudit(userID, action string, success bool, nonce string) {
	a.auditMu.Lock()
	defer a.auditMu.Unlock()
	entry := AuditEntry{
		Timestamp: time.Now(),
		UserID:    userID,
		Action:    action,
		Success:   success,
		Nonce:     nonce,
	}
	a.auditLog = append(a.auditLog, entry)
	log.Printf("[AUDIT] user=%s action=%s success=%v nonce=%s", userID, action, success, nonce)
}

func (a *Authenticator) ValidateRequest(authHeader string) (string, error) {
	// Header format: "HMAC <userID>:<nonce>:<timestamp>:<signature>"
	if !strings.HasPrefix(authHeader, "HMAC ") {
		a.logAudit("unknown", "auth_attempt", false, "")
		return "", fmt.Errorf("invalid auth scheme")
	}

	payload := strings.TrimPrefix(authHeader, "HMAC ")
	parts := strings.SplitN(payload, ":", 4)
	if len(parts) != 4 {
		a.logAudit("unknown", "auth_attempt", false, "")
		return "", fmt.Errorf("malformed auth header")
	}

	userID := parts[0]
	nonce := parts[1]
	timestampStr := parts[2]
	signature := parts[3]

	timestamp, err := strconv.ParseInt(timestampStr, 10, 64)
	if err != nil {
		a.logAudit(userID, "auth_attempt", false, nonce)
		return "", fmt.Errorf("invalid timestamp")
	}

	// Validate timestamp is within acceptable window
	now := time.Now().Unix()
	if abs(now-timestamp) > nonceWindowSeconds {
		a.logAudit(userID, "auth_attempt", false, nonce)
		return "", fmt.Errorf("request expired")
	}

	// Check nonce for replay protection BEFORE signature verification
	// This prevents replay even if signature check has timing side-channels
	nonceKey := nonce
	if !a.nonceStore.CheckAndStore(nonceKey, timestamp) {
		a.logAudit(userID, "replay_detected", false, nonce)
		return "", fmt.Errorf("replay detected")
	}

	// Verify HMAC signature
	expectedSig := a.computeSignature(userID, nonce, timestamp)
	if !hmac.Equal([]byte(signature), []byte(expectedSig)) {
		a.logAudit(userID, "auth_attempt", false, nonce)
		return "", fmt.Errorf("invalid signature")
	}

	a.logAudit(userID, "auth_success", true, nonce)
	return userID, nil
}

func (a *Authenticator) GetAuditLog() []AuditEntry {
	a.auditMu.Lock()
	defer a.auditMu.Unlock()
	entries := make([]AuditEntry, len(a.auditLog))
	copy(entries, a.auditLog)
	return entries
}

func abs(x int64) int64 {
	if x < 0 {
		return -x
	}
	return x
}
